import type { IAuth, IReport } from "@benchmark/erp-api";
import { NestiaSimulator, PlainFetcher, type IConnection } from "@nestia/fetcher";
import typia, { type Primitive, Resolved } from "typia";

/**
 * @controller ReportGenerateController.generate
 * @path GET /report-generate/:category
 * @accessor api.functional.report_generate.generate
 * @nestia Generated by Nestia - https://github.com/samchon/nestia
 */
export async function generate(
  connection: IConnection<generate.Headers>,
  category: string,
  i: generate.Query,
): Promise<generate.Output> {
  return true === connection.simulate
    ? generate.simulate(connection, category, i)
    : PlainFetcher.fetch(connection, {
        ...generate.METADATA,
        template: generate.METADATA.path,
        path: generate.path(category, i),
      });
}
export namespace generate {
  export type Headers = Resolved<IAuth.IHeaders>;
  export type Query = Resolved<IReport.IRequest>;
  export type Output = Primitive<IReport>;

  export const METADATA = {
    method: "GET",
    path: "/report-generate/:category",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
    status: 200,
  } as const;

  export const path = (category: string, i: Query) => {
    const variables: URLSearchParams = new URLSearchParams();
    for (const [key, value] of Object.entries(i as any))
      if (undefined === value) continue;
      else if (Array.isArray(value))
        value.forEach((elem: any) => variables.append(key, String(elem)));
      else variables.set(key, String(value));
    const location: string = `/report-generate/${encodeURIComponent(
      category?.toString() ?? "null",
    )}`;
    return 0 === variables.size
      ? location
      : `${location}?${variables.toString()}`;
  };
  export const random = (): Resolved<Primitive<IReport>> =>
    typia.random<Primitive<IReport>>();
  export const simulate = (
    connection: IConnection<generate.Headers>,
    category: string,
    i: Query,
  ): Output => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: path(category, i),
      contentType: "application/json",
    });
    assert.param("category")(() => typia.assert(category));
    assert.query(() => typia.assert(i));
    return random();
  };
}
